#!/usr/bin/env python3
import json
import os
import re
import sys
import tomllib
from collections import Counter
from pathlib import Path

REPO_DIR = Path(__file__).resolve().parent.parent


def slow_log_enabled(repo: Path, ansible_vars: dict) -> bool:
    """Share review-draft.py's reading of observability_mysql_slow_log."""
    import importlib.util
    spec = importlib.util.spec_from_file_location("review_draft", Path(__file__).with_name("review-draft.py"))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.slow_log_enabled(repo, ansible_vars)


# Deploying all of webapp/ copies the initial data on every release; deploy the adopted
# language and small schema/init files instead and leave the data on the nodes.
SQL_SUFFIXES = {".sql", ".sh"}
SQL_MAX_BYTES = 1024 * 1024


ROLE_RULES = {
    "nginx": ("nginx", "edge"),
    "mysql": ("mysql", "db"),
    "mariadb": ("mysql", "db"),
    "postgres": ("postgres", "db"),
    "redis": ("redis", "cache"),
    "pdns": ("dns",),
    "named": ("dns",),
}
SERVICE_TOKENS = tuple(ROLE_RULES) + ("isu",)
MANIFEST_NAMES = {
    "go.mod",
    "Cargo.toml",
    "package.json",
    "Gemfile",
    "requirements.txt",
    "pom.xml",
    "build.gradle",
}
OBSERVABILITY_TOOLS = ("sar", "perf", "alp", "slp", "stackcollapse-perf.pl", "flamegraph.pl", "offcputime-bpfcc")


def read_json(path: Path):
    with path.open() as source:
        return json.load(source)


def most_common(values: list[str]) -> str | None:
    if not values:
        return None
    return Counter(values).most_common(1)[0][0]


def infer_roles(report: dict) -> list[str]:
    haystack = "\n".join(
        report.get("running_services", []) + report.get("processes", [])
    ).lower()
    roles = {"app"}
    for needle, inferred in ROLE_RULES.items():
        if needle in haystack:
            roles.update(inferred)
    if report.get("versions", {}).get("perf"):
        roles.add("perf")
    return sorted(roles, key=lambda role: (role != "app", role))


def relevant_services(report: dict) -> set[str]:
    result = set()
    for service in report.get("running_services", []):
        lowered = service.lower()
        if any(token in lowered for token in SERVICE_TOKENS):
            result.add(service.removesuffix(".service"))
    return result


def application_root(reports: list[dict]) -> str | None:
    roots = []
    for report in reports:
        report_roots = []
        for candidate in report.get("application_candidates", []):
            path = Path(candidate)
            if path.name in MANIFEST_NAMES:
                report_roots.append(str(path.parent))
        if report_roots:
            common = os.path.commonpath(report_roots)
            if common not in ("/", "/home", "/opt", "/srv"):
                roots.append(common)
            else:
                roots.extend(report_roots)
    if not roots:
        return None
    counts = Counter(roots)
    return sorted(counts, key=lambda path: (-counts[path], "/webapp" not in path, len(path), path))[0]


def read_application_env() -> dict[str, str]:
    values = {}
    path = REPO_DIR / "config/application.env"
    if path.is_file():
        for line in path.read_text().splitlines():
            if "=" in line and not line.lstrip().startswith("#"):
                key, value = line.split("=", 1)
                values[key.strip()] = value.strip().strip("'\"")
    return values


def rust_binary_name(application_dir: Path) -> str | None:
    manifest = application_dir / "Cargo.toml"
    if not manifest.is_file():
        return None
    with manifest.open("rb") as source:
        cargo = tomllib.load(source)
    binaries = cargo.get("bin") or []
    if binaries and binaries[0].get("name"):
        return binaries[0]["name"]
    return cargo.get("package", {}).get("name")


def rust_service(service_fragments: list[str]) -> tuple[str, str] | None:
    for line in sorted(service_fragments):
        parts = line.split("\t", 1)
        if len(parts) == 2 and "rust" in parts[0] and parts[1].startswith(("/etc/systemd/system/", "/lib/systemd/system/", "/usr/lib/systemd/system/")):
            return parts[0].removesuffix(".service"), parts[1]
    return None


# Reference implementations ship one unit per language with a shared prefix (isuride-go.service,
# isuride-rust.service, isucondition.go.service); helpers such as isuride-matcher keep running.
LANGUAGE_UNIT = re.compile(
    r"^(?P<prefix>.+?)[-._](?P<language>go|golang|rust|python|ruby|node|nodejs|php|perl|java|"
    r"typescript|ts|js|crystal|elixir|csharp|dotnet)\.service$"
)


def running_units(report: dict) -> set[str]:
    return {name if name.endswith(".service") else name + ".service" for name in report.get("running_services", [])}


def language_switch(rust_unit: str, reports: dict, unit_names: set[str]) -> dict | None:
    """Nodes where another language of the same application runs instead of (or beside) Rust."""
    match = LANGUAGE_UNIT.match(rust_unit)
    if not match or match["language"] != "rust":
        return None
    siblings = {
        unit for unit in unit_names
        if (other := LANGUAGE_UNIT.match(unit)) and other["prefix"] == match["prefix"] and other["language"] != "rust"
    }
    nodes, stop = [], set()
    for node, report in sorted(reports.items()):
        # Only switch where another language of the same application is running; a node that
        # runs neither stays a review FAIL for the operator to look at.
        active = siblings & running_units(report)
        if active:
            nodes.append(node)
            stop |= active
    return {"start": rust_unit, "stop": sorted(stop), "nodes": nodes} if nodes else None


def nginx_site_items(report: dict, source_node: str) -> tuple[list[dict], list[str]]:
    """Enabled site files and conf.d files, synced at their real path (sites-enabled holds symlinks)."""
    items, warnings, seen = [], [], set()
    for line in report.get("nginx_site_files", []):
        parts = line.split("\t")
        if len(parts) != 2:
            continue
        enabled, real = parts
        name = Path(real).name
        # The measurement drop-in belongs to the Ansible bootstrap, not to the application.
        if name.startswith("00-isuscope") or real in seen:
            continue
        seen.add(real)
        stem = safe_name(name.removesuffix(".conf"))
        if real.startswith("/etc/nginx/sites-available/"):
            local, item_name = f"config/nginx/sites-available/{name}", f"nginx-site-{stem}"
        elif real.startswith("/etc/nginx/conf.d/"):
            local, item_name = f"config/nginx/conf.d/{name}", f"nginx-confd-{stem}"
        else:
            local, item_name = f"config/nginx/other/{name}", f"nginx-file-{stem}"
            warnings.append(f"Nginx loads {real} (enabled as {enabled}) from outside /etc/nginx; confirm it belongs to the application before syncing it")
        items.append({
            "name": item_name,
            "type": "file",
            "node_group": "role_nginx",
            "source_node": source_node,
            "local": local,
            "remote": real,
            "owner": "root",
            "owner_group": "root",
        })
    return items, warnings


SESSION_HEADER = re.compile(r'get\(\s*"(x-[a-z0-9-]*session[a-z0-9-]*)"', re.IGNORECASE)
SESSION_COOKIE_PATTERNS = (
    re.compile(r'Cookie::(?:new|build)\(\s*"([A-Za-z0-9_]+)"'),
    re.compile(r'\.cookie\(\s*"([A-Za-z0-9_]+)"\s*\)'),
    re.compile(r'cookie_name\(\s*"([A-Za-z0-9_]+)"'),
    re.compile(r'const\s+[A-Z0-9_]*(?:SESSION|COOKIE)[A-Z0-9_]*\s*:\s*&str\s*=\s*"([A-Za-z0-9_]+)"'),
)
NON_MYSQL_CRATES = re.compile(r'\b(rusqlite|sqlite|postgres|tokio-postgres)\b')


def session_source(application_dir: Path) -> tuple[str | None, list[str]]:
    """Guess the Nginx variable that identifies a user session from the application code."""
    headers: list[str] = []
    cookies: list[str] = []
    if application_dir.is_dir():
        for source in sorted(application_dir.rglob("*.rs")):
            if "target" in source.parts:
                continue
            text = source.read_text(errors="ignore")
            for match in SESSION_HEADER.finditer(text):
                name = match.group(1).lower()
                if name not in headers:
                    headers.append(name)
            for pattern in SESSION_COOKIE_PATTERNS:
                for match in pattern.finditer(text):
                    name = match.group(1)
                    if name not in cookies and "expire" not in name.lower():
                        cookies.append(name)
    variables = [f"$http_{name.replace('-', '_')}" for name in headers] + [f"$cookie_{name}" for name in cookies]
    # Only one of the candidates is normally present per request, so concatenation keeps the one sent.
    return ("".join(variables) if variables else None), headers + cookies


def application_database_warnings(application_dir: Path) -> list[str]:
    manifest = application_dir / "Cargo.toml"
    if not manifest.is_file():
        return []
    found = sorted(set(NON_MYSQL_CRATES.findall(manifest.read_text(errors="ignore"))))
    if not found:
        return []
    return [f"the application depends on {', '.join(found)}; isuscope collects database metrics only from MySQL (the slow log and Performance Schema)"]


def safe_name(value: str) -> str:
    return re.sub(r"[^A-Za-z0-9_.-]+", "-", value).strip("-.")


def application_owner(reports: list[dict], root: str | None) -> tuple[str, str] | None:
    if not root:
        return None
    owners = []
    root_path = Path(root)
    for report in reports:
        for line in report.get("application_candidate_ownership", []):
            parts = line.split("\t")
            if len(parts) != 3:
                continue
            path, owner, group = parts
            try:
                Path(path).relative_to(root_path)
            except ValueError:
                continue
            owners.append((owner, group))
    if not owners:
        return None
    return Counter(owners).most_common(1)[0][0]


def mysql_config_items(mysql_root, source_node, observed):
    if mysql_root == '/etc/mysql':
        # Do not collect node-specific debian.cnf credentials with the directory.
        paths = [('conf.d', 'directory'), ('mysql.conf.d', 'directory'), ('mysql.cnf', 'file'), ('mariadb.conf.d', 'directory'), ('mariadb.cnf', 'file')]
        if not any('/etc/mysql/' + n in observed for n in ('mysql.cnf','mariadb.cnf')):
            paths.append(('my.cnf','file'))
        return [dict(name='mysql-' + name, type=kind, node_group='role_mysql', source_node=source_node,
                     local='config/mysql/' + name, remote='/etc/mysql/' + name,
                     owner='root', owner_group='root') for name, kind in paths if '/etc/mysql/' + name in observed]
    if mysql_root == '/etc/my.cnf':
        return [dict(name='mysql-conf', type='file', node_group='role_mysql', source_node=source_node,
                     local='config/mysql/my.cnf', remote='/etc/my.cnf', owner='root', owner_group='root')]
    return []


def main() -> int:
    if len(sys.argv) != 4:
        print(f"usage: {sys.argv[0]} INVENTORY INSPECTION_DIR OUTPUT_DIR", file=sys.stderr)
        return 2
    inventory_path, inspection_dir, output_dir = map(Path, sys.argv[1:])
    inventory = read_json(inventory_path)
    application_hosts = inventory["all"]["children"]["application"]["hosts"]
    reports = {}
    for node in application_hosts:
        report_path = inspection_dir / f"{node}.json"
        if not report_path.is_file():
            print(f"missing inspection report: {report_path}", file=sys.stderr)
            return 1
        reports[node] = read_json(report_path)

    output_dir.mkdir(parents=True, exist_ok=True)
    discovered_path = inventory_path.parent / "discovered-nodes.json"
    discovered = read_json(discovered_path)
    roles_by_node = {node: infer_roles(report) for node, report in reports.items()}
    draft_nodes = []
    for node in discovered:
